mapper.insert:

    SELECT fn_get_dynamic_seq('utb_memo') AS memoSeq


/* 1. 메모 본체 저장 (오타 수정: memo_rag_date -> memo_reg_date) */
INSERT INTO "MP_IPMS_PA".utb_memo (
memo_seq, must_read_yn, memo_title, customer_name,
memo_reg_date, note, create_user, create_at, update_user, update_at, del_yn
) VALUES (
#{memoSeq}, COALESCE(#{mustReadYn}, 'N'), #{memoTitle}, #{customerName},
#{memoRegDate}, #{note}, #{createUser}, CURRENT_TIMESTAMP, #{updateUser}, CURRENT_TIMESTAMP, 'N'
);

/* 2. 매핑 테이블 저장 */
INSERT INTO "MP_IPMS_PA".utb_memo_mapp (
memo_mapp_seq, office_seq, tbl_seq, memo_seq, tbl_code,
create_user, create_at, update_user, update_at, del_yn
) VALUES (
fn_get_dynamic_seq('utb_memo_mapp'),
#{officeSeq}, #{tblSeq}, #{memoSeq}, #{tblCode},
#{createUser}, CURRENT_TIMESTAMP, #{updateUser}, CURRENT_TIMESTAMP, 'N'
);

mapper.select:
SELECT
    COUNT(1)
FROM utb_memo um
INNER JOIN utb_memo_mapp umm ON um.memo_seq = umm.memo_seq
WHERE umm.office_seq = #{officeSeq}
  AND umm.tbl_seq = #{tblSeq}
  AND um.memo_seq = #{memoSeq}
  AND um.del_yn = 'N'
  AND umm.del_yn = 'N'

mapper.update:
UPDATE utb_memo
SET del_yn = 'Y',
    update_user = #{userSeq},
    update_at = CURRENT_TIMESTAMP
WHERE memo_seq = #{memoSeq}
  AND memo_seq IN (
      SELECT memo_seq FROM utb_memo_mapp
      WHERE tbl_seq = #{tblSeq}
        AND office_seq = #{officeSeq}
        AND del_yn = 'N'
  )
  AND del_yn = 'N'

UPDATE utb_memo_mapp
SET del_yn = 'Y',
    update_user = #{userSeq},
    update_at = CURRENT_TIMESTAMP
WHERE tbl_seq = #{tblSeq}
  AND office_seq = #{officeSeq}
  AND memo_seq = #{memoSeq}
  AND del_yn = 'N'

